<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Peminjaman Alat</title></head><body><h1>Sistem Peminjaman Alat</h1>
<?php if(session('berhasil')): ?><p><?php echo e(session('berhasil')); ?></p><?php endif; ?> <?php if(session('gagal')): ?><p><?php echo e(session('gagal')); ?></p><?php endif; ?> <?php if($errors->any()): ?><ul><?php $__currentLoopData = $errors->all(); $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $error): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><li><?php echo e($error); ?></li><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></ul><?php endif; ?>
