<form method="GET"><input name="q" placeholder="Cari kode/nama/identitas" value="<?php echo e($q); ?>"><select name="alat_id"><option value="">Semua alat</option><?php $__currentLoopData = $alat; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $item): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($item['id']); ?>" <?php if((string)$alatId===(string)$item['id']): echo 'selected'; endif; ?>><?php echo e($item['nama_alat']); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><button>Cari</button></form>
